// Read-only matching-build metadata for candidate investigation, not gameplay proof.
static void ReadSecondPetSpellCandidates(){
 for(char const*name:{"spell_slimbering_gasp","spell_neesa_ogre_traps","spell_felhounds_touched_proc","spell_deepbeard_gaseous_explosion","spell_hyrja_eye_storm_absorb","spell_power_of_the_twins","spell_alexstrasza_gift_beam_visual","spell_most_complicated_bomb","spell_pri_smite_absorb","spell_gen_intangible_presence","spell_gen_shadowy_reflection","spell_gen_guiding_hand","spell_gen_shadowy_reflection_absorb","spell_gen_brutal_haymaker","spell_gen_misc","spell_dru_natures_guardian","spell_pal_holy_wrath","spell_gen_touch_the_nightmare","spell_small_sha_fixate","spell_highmaul_enfeebling_roar","spell_highmaul_flamethrower_overrider"}){
  auto rows=WorldDatabase.PQuery("SELECT spell_id FROM spell_script_names WHERE ScriptName='%s'",name);if(!rows){std::cout<<"SPELL_META_UNBOUND "<<name<<"\n";continue;}
  do{uint32 id=rows->Fetch()[0].GetUInt32();auto info=sSpellMgr->GetSpellInfo(id);Require(info,"Candidate binding has no matching native spell");std::cout<<"SPELL_META "<<name<<" id="<<id<<" duration="<<info->GetDuration()<<" ticks="<<info->GetMaxTicks()<<"\n";for(auto effect:info->Effects)if(effect&&effect->Effect)std::cout<<"SPELL_EFFECT "<<id<<" index="<<uint32(effect->EffectIndex)<<" effect="<<effect->Effect<<" aura="<<effect->ApplyAuraName<<" period="<<effect->ApplyAuraPeriod<<" targetA="<<effect->TargetA.GetTarget()<<" targetB="<<effect->TargetB.GetTarget()<<" points="<<effect->BasePoints<<"\n";}while(rows->NextRow());
 }
 for(uint32 id=1;id<sSpellMgr->GetSpellInfoStoreSize();++id){auto info=sSpellMgr->GetSpellInfo(id);if(!info||!info->HasAura(SPELL_AURA_PERIODIC_WEAPON_PERCENT_DAMAGE)||info->GetDuration()<=0)continue;for(auto effect:info->Effects)if(effect&&effect->ApplyAuraName==SPELL_AURA_PERIODIC_WEAPON_PERCENT_DAMAGE&&effect->ApplyAuraPeriod){uint32 expected=uint32(std::min(info->GetDuration(),30000))/effect->ApplyAuraPeriod;if(expected!=info->GetMaxTicks())std::cout<<"WEAPON_TICK_CANDIDATE "<<id<<" duration="<<info->GetDuration()<<" period="<<effect->ApplyAuraPeriod<<" actual="<<info->GetMaxTicks()<<" expected="<<expected<<"\n";}}
}
